#include <cmath>
#include <complex>
#include <constants_mod.hpp>
#include <Need.hpp>

std::complex<double> lnrat(double x, double y) {
  using namespace constants_mod;

  // define Heaviside theta function (=1 for x>0) and (0 for x < 0)
  auto htheta = [&](double x) -> double {
    return half + half*sign(x);
  };

  return cplx1(std::log(std::abs(x/y))) - impi*(htheta(-x) - htheta(-y));
}

extern"C"{
 std:: complex<double> lnrat_wrapper(double x, double y) {
    return lnrat(x,y);
  }
}
