// Z. Bern, L. Dixon, D.A. Kosower, e-Print:hep-ph/9708239
// Eq10.6

std::complex<double> FFPPsc1(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
  auto zab = [&za, &zb](int i1, int i2, int i3) {
    return za(i1, i2) * zb(i2, i3);
  };

  return (za(j4, j1) * za(j5, j2) - za(j2, j4) * za(j5, j1)) * zab(j5, j4, j3)
      / (za(j3, j4) * std::pow(za(j4, j1), 2) * za(j5, j6));
}

std::complex<double> FFPPsc2(int j1, int j2, int j3, int j4, int j5, int j6, FArray2D<std::complex<double>>& za, FArray2D<std::complex<double>>& zb) {
